/**
 * Pure parsing of Roundcube 1.6 responses. No IO.
 *
 * AJAX responses are JSON `{action, env, texts, exec}`; `exec` is a newline-separated
 * list of `this.<method>(<json args>);` calls generated by rcube_output_json::command().
 * Page responses are HTML whose state lives in `rcmail.set_env({...})` and in forms.
 */
import { parseHTML } from "linkedom";

// linkedom exports no Element type; derive it from the parser it does export.
type El = NonNullable<ReturnType<ReturnType<typeof parseHTML>["document"]["querySelector"]>>;

export interface ExecCall {
  method: string;
  args: unknown[];
}

const CALL_RE = /^(?:parent\.)?(?:this|rcmail)\.([\w$.]+)\((.*)\);?$/;

/** Split a Roundcube `exec` script into calls. JSON args never contain raw newlines. */
export function parseExec(exec: string | undefined): ExecCall[] {
  if (!exec) return [];
  const calls: ExecCall[] = [];
  for (const raw of exec.split("\n")) {
    const line = raw.trim();
    if (!line) continue;
    const m = CALL_RE.exec(line);
    if (!m) continue;
    let args: unknown[];
    try {
      args = JSON.parse(`[${m[2]}]`) as unknown[];
    } catch {
      args = [m[2]];
    }
    calls.push({ method: m[1]!, args });
  }
  return calls;
}

export interface AjaxResult {
  action?: string;
  env: Record<string, unknown>;
  texts: Record<string, string>;
  calls: ExecCall[];
  /** Arguments of display_message(..., "error"|"warning") calls. */
  errors: string[];
  /** Arguments of display_message(..., "confirmation") calls. */
  notices: string[];
  sessionExpired: boolean;
}

export function parseAjax(body: string): AjaxResult {
  let json: { action?: string; env?: Record<string, unknown>; texts?: Record<string, string>; exec?: string };
  try {
    json = JSON.parse(body);
  } catch {
    throw new Error(`webmail returned a non-JSON response: ${body.slice(0, 200)}`);
  }
  const calls = parseExec(json.exec);
  const sessionExpired = calls.some((c) => c.method === "session_error");
  return { action: json.action, env: json.env ?? {}, texts: json.texts ?? {}, calls, ...displayMessages(calls), sessionExpired };
}

/** Collect user-facing `display_message(text, type)` calls: errors/warnings vs confirmations. */
export function displayMessages(calls: ExecCall[]): { errors: string[]; notices: string[] } {
  const errors: string[] = [];
  const notices: string[] = [];
  for (const c of calls) {
    if (c.method !== "display_message") continue;
    const [msg, type] = c.args as [string, string];
    if (type === "error" || type === "warning") errors.push(stripTags(String(msg)));
    else if (type === "confirmation" || type === "notice") notices.push(stripTags(String(msg)));
  }
  return { errors, notices };
}

export function callsOf(r: { calls: ExecCall[] }, method: string): unknown[][] {
  return r.calls.filter((c) => c.method === method).map((c) => c.args);
}

const ENTITIES: Record<string, string> = { amp: "&", lt: "<", gt: ">", quot: '"', apos: "'", nbsp: " " };

export function decodeEntities(s: string): string {
  return s.replace(/&(#x[0-9a-f]+|#\d+|\w+);/gi, (all, e: string) => {
    if (e[0] === "#") {
      const code = e[1] === "x" || e[1] === "X" ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
      return Number.isFinite(code) ? String.fromCodePoint(code) : all;
    }
    return ENTITIES[e.toLowerCase()] ?? all;
  });
}

export function stripTags(html: string): string {
  return decodeEntities(html.replace(/<[^>]*>/g, "")).trim();
}

export interface Address {
  name: string;
  email: string;
}

/** Parse the `fromto` column: `<span class="adr"><span title="a@b" ...>Name</span></span>`, possibly several. */
export function parseAddressCell(html: string): Address[] {
  const out: Address[] = [];
  const re = /<span[^>]*\btitle="([^"]*)"[^>]*>(.*?)<\/span>/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(html))) {
    const email = decodeEntities(m[1]!);
    out.push({ email, name: stripTags(m[2]!) });
  }
  if (!out.length) {
    const text = stripTags(html);
    if (text) out.push({ name: text, email: /@/.test(text) ? text : "" });
  }
  return out;
}

export interface MessageRow {
  uid: number;
  mbox: string;
  subject: string;
  from: Address[];
  date: string;
  size: string;
  seen: boolean;
  flagged: boolean;
  answered: boolean;
  forwarded: boolean;
  deleted: boolean;
  hasAttachment: boolean;
  priority?: number;
  contentType?: string;
  depth?: number;
  parentUid?: number;
}

/** Turn `add_message_row(uid, cols, flags, attop)` calls into rows. */
export function messageRows(r: { calls: ExecCall[] }, fallbackMbox: string): MessageRow[] {
  return callsOf(r, "add_message_row").map(([uid, cols, flags]) => {
    const c = (cols ?? {}) as Record<string, string>;
    const f = (flags ?? {}) as Record<string, unknown>;
    const row: MessageRow = {
      // Multi-folder search rows are keyed `<uid>-<encoded folder>`; the folder is in flags.mbox.
      uid: parseInt(String(uid), 10),
      mbox: typeof f.mbox === "string" ? f.mbox : fallbackMbox,
      subject: stripTags(c.subject ?? ""),
      from: parseAddressCell(c.fromto ?? c.from ?? c.to ?? ""),
      date: stripTags(c.date ?? ""),
      size: stripTags(c.size ?? ""),
      seen: Boolean(f.seen),
      flagged: Boolean(f.flagged),
      answered: Boolean(f.answered),
      forwarded: Boolean(f.forwarded),
      deleted: Boolean(f.deleted),
      hasAttachment: Boolean(f.hasattachment) || (!f.hasnoattachment && /multipart\/(mixed|signed|report)/.test(String(f.ctype ?? ""))),
    };
    if (typeof f.prio === "number") row.priority = f.prio;
    if (typeof f.ctype === "string") row.contentType = f.ctype;
    if (typeof f.depth === "number") row.depth = f.depth;
    if (f.parent_uid !== undefined) row.parentUid = Number(f.parent_uid);
    return row;
  });
}

/** Extract the object passed to `rcmail.set_env({...})` on an HTML page (merged if repeated). */
export function pageEnv(html: string): Record<string, unknown> {
  const env: Record<string, unknown> = {};
  const re = /rcmail\.set_env\((\{.*?\})\);\s*(?:\n|rcmail\.|<\/script>|$)/gs;
  let m: RegExpExecArray | null;
  while ((m = re.exec(html))) {
    try {
      Object.assign(env, JSON.parse(m[1]!));
    } catch {
      /* not a plain JSON env block */
    }
  }
  return env;
}

/** Calls embedded in a page's inline script: `rcmail.method(args);` or `parent.rcmail.method(args);`. */
export function pageCalls(html: string): ExecCall[] {
  const calls: ExecCall[] = [];
  const scripts = html.match(/<script[^>]*>([\s\S]*?)<\/script>/g) ?? [];
  for (const s of scripts) {
    const body = s.replace(/^<script[^>]*>|<\/script>$/g, "");
    for (const line of body.split(/\n|;(?=\s*(?:parent\.)?(?:rcmail|this)\.)/)) {
      const t = line.trim().replace(/^.*?((?:parent\.)?(?:rcmail|this)\.)/, "$1");
      calls.push(...parseExec(t.endsWith(")") ? `${t};` : t));
    }
  }
  return calls;
}

export interface FormField {
  name: string;
  /** input type, or "select"/"textarea" */
  type: string;
  value: string;
  checked?: boolean;
  multiple?: boolean;
  options?: { value: string; label: string; selected: boolean }[];
  label?: string;
  disabled?: boolean;
}

export interface HtmlForm {
  name: string;
  id: string;
  action: string;
  method: string;
  fields: FormField[];
}

/** Form id given to controls that sit outside every <form> (e.g. Elastic's compose options). */
export const ORPHAN_FORM = "#orphans";

/**
 * Parse all <form> elements on a page with their fields and current values. Controls outside
 * any form are collected into a trailing pseudo-form with id ORPHAN_FORM.
 */
export function parseForms(html: string): HtmlForm[] {
  const { document } = parseHTML(html);
  const labels = new Map<string, string>();
  for (const l of document.querySelectorAll("label[for]")) {
    labels.set(l.getAttribute("for") ?? "", (l.textContent ?? "").trim());
  }
  // Settings forms render the label in the first cell of the same table row.
  const rowLabel = (el: El): string | undefined => {
    const id = el.getAttribute("id");
    if (id && labels.get(id)) return labels.get(id);
    const row = el.closest("tr, .form-group");
    const t = row?.querySelector("td.title, label.col-form-label, .col-form-label, th")?.textContent?.trim();
    return t || undefined;
  };
  const fieldsOf = (controls: Iterable<El>): FormField[] => {
    const fields: FormField[] = [];
    for (const el of controls) {
      const name = el.getAttribute("name");
      if (!name) continue;
      const tag = el.tagName.toLowerCase();
      const disabled = el.hasAttribute("disabled") || undefined;
      const label = rowLabel(el);
      if (tag === "select") {
        const options = [...el.querySelectorAll("option")].map((o) => ({
          value: o.getAttribute("value") ?? (o.textContent ?? "").trim(),
          label: (o.textContent ?? "").trim(),
          selected: o.hasAttribute("selected"),
        }));
        const multiple = el.hasAttribute("multiple") || undefined;
        const sel = options.filter((o) => o.selected);
        const value = multiple ? sel.map((o) => o.value).join(",") : (sel[0] ?? options[0])?.value ?? "";
        fields.push({ name, type: "select", value, options, multiple, label, disabled });
      } else if (tag === "textarea") {
        // linkedom keeps textarea content as raw RCDATA; browsers decode its entities.
        fields.push({ name, type: "textarea", value: decodeEntities(el.innerHTML ?? ""), label, disabled });
      } else {
        const type = (el.getAttribute("type") ?? "text").toLowerCase();
        if (type === "submit" || type === "button" || type === "image" || type === "reset") continue;
        const field: FormField = { name, type, value: el.getAttribute("value") ?? (type === "checkbox" || type === "radio" ? "on" : ""), label, disabled };
        if (type === "checkbox" || type === "radio") field.checked = el.hasAttribute("checked");
        fields.push(field);
      }
    }
    return fields;
  };
  const forms: HtmlForm[] = [];
  for (const f of document.querySelectorAll("form")) {
    forms.push({
      name: f.getAttribute("name") ?? "",
      id: f.getAttribute("id") ?? "",
      action: f.getAttribute("action") ?? "",
      method: (f.getAttribute("method") ?? "get").toLowerCase(),
      fields: fieldsOf(f.querySelectorAll("input, select, textarea")),
    });
  }
  const orphans = [...document.querySelectorAll("input, select, textarea")].filter((el) => !el.closest("form"));
  forms.push({ name: "", id: ORPHAN_FORM, action: "", method: "post", fields: fieldsOf(orphans) });
  return forms;
}

/** Serialize fields the way a browser submits them (unchecked boxes and disabled fields omitted). */
export function serializeForm(fields: FormField[]): [string, string][] {
  const out: [string, string][] = [];
  for (const f of fields) {
    if (f.disabled || f.type === "file") continue;
    if ((f.type === "checkbox" || f.type === "radio") && !f.checked) continue;
    if (f.type === "select" && f.multiple) {
      for (const v of f.value ? f.value.split(",") : []) out.push([f.name, v]);
      continue;
    }
    out.push([f.name, f.value]);
  }
  return out;
}

/**
 * Apply `key=value` edits to a form. Checkboxes take on/off/true/false/1/0, radios select the
 * matching value, selects accept an option value or label. Unknown keys are an error so typos
 * cannot silently do nothing.
 */
export function applyEdits(fields: FormField[], edits: Record<string, string>): FormField[] {
  const out = fields.map((f) => ({ ...f, options: f.options?.map((o) => ({ ...o })) }));
  for (const [rawKey, value] of Object.entries(edits)) {
    const key = rawKey.startsWith("_") ? rawKey : `_${rawKey}`;
    const matches = out.filter((f) => f.name === key || f.name === rawKey);
    if (!matches.length) {
      const known = [...new Set(out.filter((f) => f.type !== "hidden").map((f) => f.name.replace(/^_/, "")))].join(", ");
      throw new Error(`unknown field "${rawKey}". Fields: ${known}`);
    }
    const first = matches[0]!;
    if (first.type === "checkbox" && matches.length > 1) {
      // A checkbox group (`name[]` repeated): value lists the values to check, "-" for none.
      const wanted = value === "-" ? [] : value.split(",").map((v) => v.trim());
      const bad = wanted.filter((w) => !matches.some((f) => f.value === w));
      if (bad.length) throw new Error(`${rawKey} values must be from: ${matches.map((f) => f.value).join(", ")}`);
      for (const f of matches) f.checked = wanted.includes(f.value);
    } else if (first.type === "checkbox") {
      const on = /^(1|on|true|yes)$/i.test(value);
      if (!on && !/^(0|off|false|no)$/i.test(value)) throw new Error(`${rawKey} is a checkbox: use on or off`);
      first.checked = on;
    } else if (first.type === "radio") {
      const hit = matches.find((f) => f.value === value);
      if (!hit) throw new Error(`${rawKey} must be one of: ${matches.map((f) => f.value).join(", ")}`);
      for (const f of matches) f.checked = f === hit;
    } else if (first.type === "select") {
      const opts = first.options ?? [];
      const wanted = first.multiple ? value.split(",").map((v) => v.trim()).filter(Boolean) : [value];
      const resolved = wanted.map((w) => {
        const o = opts.find((o) => o.value === w) ?? opts.find((o) => o.label.toLowerCase() === w.toLowerCase());
        if (!o) throw new Error(`${rawKey} must be one of: ${opts.map((o) => (o.label && o.label !== o.value ? `${o.value} (${o.label})` : o.value)).join(", ")}`);
        return o.value;
      });
      first.value = resolved.join(",");
      for (const o of opts) o.selected = resolved.includes(o.value);
    } else {
      first.value = value;
    }
  }
  return out;
}
